CREATE TABLE IF NOT EXISTS "service_policy_releases" (
  "policy_version" varchar(32) PRIMARY KEY NOT NULL,
  "status" varchar(32) NOT NULL DEFAULT 'draft',
  "reason" varchar(1024) NOT NULL,
  "published_by" varchar(128),
  "published_at" timestamp with time zone,
  "created_at" timestamp with time zone NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS "service_policy_capabilities" (
  "id" varchar(128) PRIMARY KEY NOT NULL,
  "slug" varchar(160) NOT NULL,
  "vertical" varchar(120) NOT NULL,
  "name" varchar(160) NOT NULL,
  "description" varchar(2000) NOT NULL,
  "risk_tier" varchar(32) NOT NULL,
  "release_scope" varchar(32) NOT NULL,
  "aliases" jsonb NOT NULL DEFAULT '[]'::jsonb,
  "version" varchar(32) NOT NULL,
  "policy_version" varchar(32) NOT NULL,
  "status" varchar(32) NOT NULL DEFAULT 'draft',
  "creator_selectable" boolean NOT NULL DEFAULT true,
  "publish_enabled" boolean NOT NULL DEFAULT true,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at" timestamp with time zone NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS "service_policy_capabilities_status_idx" ON "service_policy_capabilities" ("status", "policy_version");
CREATE TABLE IF NOT EXISTS "service_policy_templates" (
  "id" varchar(128) PRIMARY KEY NOT NULL,
  "slug" varchar(160) NOT NULL,
  "capability_catalog_item_id" varchar(128) NOT NULL,
  "name" varchar(160) NOT NULL,
  "description" varchar(2000) NOT NULL,
  "risk_tier" varchar(32) NOT NULL,
  "release_scope" varchar(32) NOT NULL,
  "required_fields" jsonb NOT NULL DEFAULT '[]'::jsonb,
  "version" varchar(32) NOT NULL,
  "policy_version" varchar(32) NOT NULL,
  "status" varchar(32) NOT NULL DEFAULT 'draft',
  "creator_selectable" boolean NOT NULL DEFAULT true,
  "publish_enabled" boolean NOT NULL DEFAULT true,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at" timestamp with time zone NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS "service_policy_templates_capability_idx" ON "service_policy_templates" ("capability_catalog_item_id");
CREATE INDEX IF NOT EXISTS "service_policy_templates_status_idx" ON "service_policy_templates" ("status", "policy_version");
CREATE UNIQUE INDEX IF NOT EXISTS "service_policy_capabilities_version_uq" ON "service_policy_capabilities" ("id", "policy_version");
CREATE UNIQUE INDEX IF NOT EXISTS "service_policy_templates_version_uq" ON "service_policy_templates" ("id", "policy_version");
CREATE TABLE IF NOT EXISTS "service_policy_audits" (
  "id" varchar(128) PRIMARY KEY NOT NULL,
  "actor_id" varchar(128) NOT NULL,
  "entity_type" varchar(32) NOT NULL,
  "entity_id" varchar(128) NOT NULL,
  "action" varchar(32) NOT NULL,
  "before_state" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "after_state" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "reason" varchar(1024) NOT NULL,
  "policy_version" varchar(32) NOT NULL,
  "occurred_at" timestamp with time zone NOT NULL,
  "correlation_id" varchar(128) NOT NULL,
  "recorded_at" timestamp with time zone NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS "service_policy_audits_entity_idx" ON "service_policy_audits" ("entity_type", "entity_id", "occurred_at");
CREATE INDEX IF NOT EXISTS "service_policy_audits_actor_idx" ON "service_policy_audits" ("actor_id", "occurred_at");
INSERT INTO "service_policy_releases" ("policy_version", "status", "reason", "published_at") VALUES ('v1', 'published', 'Initial controlled service policy catalog', now()) ON CONFLICT ("policy_version") DO NOTHING;
